// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {ISovereignPool} from "./ISovereignPool.sol";
import {IHOT} from "@valantis-hot/contracts/interfaces/IHOT.sol";
import {IOracleWrapper} from "./IOracleWrapper.sol";

interface IValantisHOTModule {
    // #region errors.

    /// @notice
    error NoNativeToken();
    error OnlyPool(address caller, address pool);
    error AmountsZeros();
    error NotImplemented();
    error ExpectedMinReturnTooLow();
    error MaxSlippageGtTenPercent();
    error NotDepositedAllToken0();
    error NotDepositedAllToken1();
    error OnlyMetaVaultOwner();
    error ALMAlreadySet();
    error SlippageTooHigh();
    error NotEnoughToken0();
    error NotEnoughToken1();
    error SwapCallFailed();
    error OverMaxDeviation();
    error WrongRouter();

    // #endregion errors.

    // #region events.

    event LogSetALM(address alm);
    event LogInitializePosition(uint256 amount0, uint256 amount1);
    event LogSwap(
        uint256 oldBalance0,
        uint256 oldBalance1,
        uint256 newBalance0,
        uint256 newBalance1
    );

    // #endregion events.

    // #region state modifying functions.

    /// @notice initialize function to delegate call onced the beacon proxy is deployed,
    /// for initializing the valantis module.
    /// who can call deposit and withdraw functions.
    /// @param pool_ address of the valantis sovereign pool.
    /// @param init0_ initial amount of token0 to provide to valantis module.
    /// @param init1_ initial amount of token1 to provide to valantis module.
    /// @param maxSlippage_ allowed to manager for rebalancing the inventory using
    /// swap.
    /// @param metaVault_ address of the meta vault
    function initialize(
        address pool_,
        uint256 init0_,
        uint256 init1_,
        uint24 maxSlippage_,
        address metaVault_
    ) external;

    /// @notice set HOT and initialize manager fees function.
    /// @param alm_ address of the valantis HOT ALM.
    /// @param oracle_ address of the oracle used by the valantis HOT module.
    function setALMAndManagerFees(
        address alm_,
        address oracle_
    ) external;

    /// @notice fucntion used to set range on valantis AMM
    /// @param _sqrtPriceLowX96 lower bound of the range in sqrt price.
    /// @param _sqrtPriceHighX96 upper bound of the range in sqrt price.
    /// @param _expectedSqrtSpotPriceLowerX96 expected upper limit of current spot
    /// price (to prevent sandwich attack and manipulation).
    /// @param _expectedSqrtSpotPriceUpperX96 expected lower limit of current spot
    /// price (to prevent sandwich attack and manipulation).
    function setPriceBounds(
        uint160 _sqrtPriceLowX96,
        uint160 _sqrtPriceHighX96,
        uint160 _expectedSqrtSpotPriceLowerX96,
        uint160 _expectedSqrtSpotPriceUpperX96
    ) external;

    /// @notice function to swap token0->token1 or token1->token0 and then change
    /// inventory.
    /// @param zeroForOne_ boolean if true token0->token1, if false token1->token0.
    /// @param expectedMinReturn_ minimum amount of tokenOut expected.
    /// @param amountIn_ amount of tokenIn used during swap.
    /// @param router_  address of smart contract that will execute swap.
    /// @param expectedSqrtSpotPriceUpperX96_ upper bound of current price.
    /// @param expectedSqrtSpotPriceLowerX96_ lower bound of current price.
    /// @param payload_ data payload used for swapping.
    function swap(
        bool zeroForOne_,
        uint256 expectedMinReturn_,
        uint256 amountIn_,
        address router_,
        uint160 expectedSqrtSpotPriceUpperX96_,
        uint160 expectedSqrtSpotPriceLowerX96_,
        bytes calldata payload_
    ) external;

    // #endregion state modifiying functions.

    // #region view functions.

    /// @notice function used to get the valantis hot pool.
    function pool() external view returns (ISovereignPool);

    /// @notice function used to get the valantis hot alm/ liquidity module.
    function alm() external view returns (IHOT);

    /// @notice function used to get the max slippage that
    /// can occur during swap rebalance.
    function maxSlippage() external view returns (uint24);

    /// @notice function used to get the oracle that
    /// will be used to proctect rebalances.
    function oracle() external view returns (IOracleWrapper);

    // #endregion view functions.
}

src/modules/ValantisHOTModulePublic.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.19;

import {IArrakisLPModulePublic} from
    "../interfaces/IArrakisLPModulePublic.sol";
import {ValantisModule} from "../abstracts/ValantisHOTModule.sol";
import {BASE} from "../constants/CArrakis.sol";

import {SafeERC20} from
    "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC20Metadata} from
    "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";

import {FullMath} from "@v3-lib-0.8/contracts/FullMath.sol";

contract ValantisModulePublic is
    ValantisModule,
    IArrakisLPModulePublic
{
    using SafeERC20 for IERC20Metadata;

    bool public notFirstDeposit;

    constructor(address guardian_) ValantisModule(guardian_) {}

    /// @notice deposit function for public vault.
    /// @param depositor_ address that will provide the tokens.
    /// @param proportion_ percentage of portfolio position vault want to expand.
    /// @return amount0 amount of token0 needed to expand the portfolio by "proportion"
    /// percent.
    /// @return amount1 amount of token1 needed to expand the portfolio by "proportion"
    /// percent.
    function deposit(
        address depositor_,
        uint256 proportion_
    )
        external
        payable
        onlyMetaVault
        whenNotPaused
        nonReentrant
        returns (uint256 amount0, uint256 amount1)
    {
        if (msg.value > 0) revert NoNativeToken();
        if (depositor_ == address(0)) revert AddressZero();
        if (proportion_ == 0) revert ProportionZero();

        // #region effects.

        {
            (uint256 _amt0, uint256 _amt1) = pool.getReserves();

            if (!notFirstDeposit) {
                if (_amt0 > 0 || _amt1 > 0) {
                    // #region send dust on pool to manager.

                    address manager = metaVault.manager();

                    alm.withdrawLiquidity(_amt0, _amt1, manager, 0, 0);

                    // #endregion send dust on pool to manager.
                }

                _amt0 = _init0;
                _amt1 = _init1;
                notFirstDeposit = true;
            }

            amount0 =
                FullMath.mulDivRoundingUp(proportion_, _amt0, BASE);
            amount1 =
                FullMath.mulDivRoundingUp(proportion_, _amt1, BASE);
        }

        // #region get the tokens from the depositor.

        token0.safeTransferFrom(depositor_, address(this), amount0);
        token1.safeTransferFrom(depositor_, address(this), amount1);

        // #endregion get the tokens from the depositor.

        // #region increase allowance to alm.

        token0.forceApprove(address(alm), amount0);
        token1.forceApprove(address(alm), amount1);

        // #endregion increase allowance to alm.

        alm.depositLiquidity(amount0, amount1, 0, 0);

        // #endregion interactions.

        emit LogDeposit(depositor_, proportion_, amount0, amount1);
    }

    /// @notice function used by metaVault to withdraw tokens from the strategy.
    /// @param receiver_ address that will receive tokens.
    /// @param proportion_ number of share needed to be withdrawn.
    /// @return amount0 amount of token0 withdrawn.
    /// @return amount1 amount of token1 withdrawn.
    function withdraw(
        address receiver_,
        uint256 proportion_
    ) public override returns (uint256 amount0, uint256 amount1) {
        if (proportion_ == BASE) {
            notFirstDeposit = false;
        }
        return super.withdraw(receiver_, proportion_);
    }

    function initializePosition(bytes calldata data_)
        external
        override
        onlyMetaVault
    {
        notFirstDeposit = true;
        _initializePosition();
    }
}

